-- Approved E rulings. Only v16 activates these private helpers.
create or replace function ml_private.p3e_enabled(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(s->>'version'='web-v0.1.16',false)$$;
create or replace function ml_private.p3e_start(s jsonb,a integer) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$begin
 if not ml_private.p3e_enabled(s) then return s;end if;
 s:=jsonb_set(s,'{stage3,e}',coalesce(s#>'{stage3,e}','{"current":"initial","permissions":{},"eggUsed":{},"moved":{},"escapeUsed":[false,false,false,false]}'::jsonb));
 s:=jsonb_set(s,'{stage3,e}',(s#>'{stage3,e}')||jsonb_build_object('current','turn'||greatest(1,(s#>>'{stage3,turn}')::int),'permissions','{}'::jsonb,'eggUsed','{}'::jsonb,'moved','{}'::jsonb));return jsonb_set(s,array['stage3','e','escapeUsed',a::text],'false');end $$;
create or replace function ml_private.p3e_valid(s jsonb) returns boolean language sql immutable set search_path=pg_catalog,ml_private as $$select not ml_private.p3e_enabled(s) or coalesce(jsonb_typeof(s#>'{stage3,e,current}')='string' and not exists(select 1 from unnest(array['permissions','eggUsed','moved']) k where jsonb_typeof(s#>array['stage3','e',k])<>'object' or exists(select 1 from jsonb_each(s#>array['stage3','e',k]) q where jsonb_typeof(value)<>'boolean')) and s#>'{stage3,e}' ?& array['permissions','eggUsed','moved'] and jsonb_typeof(s#>'{stage3,e,escapeUsed}')='array' and jsonb_array_length(s#>'{stage3,e,escapeUsed}')=4 and not exists(select 1 from ml_private.arr(s#>'{stage3,e,escapeUsed}') v where jsonb_typeof(v)<>'boolean'),false)$$;
create or replace function ml_private.p3e_root(s jsonb) returns text language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(s#>>'{cardStack,stack,0,serial}',case when s->'movement'<>'null'::jsonb then 'move'||(s#>>'{movement,gearRoot}') else s#>>'{stage3,e,current}' end)$$;
create or replace function ml_private.p3e_gate(s jsonb,target integer,source integer,resume jsonb,root text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare k text:=root||':'||coalesce(source::text,'environment')||':'||target;allowed jsonb:=s#>array['stage3','e','permissions',k];begin
 if not ml_private.p3e_enabled(s) or s#>>array['players',target::text,'character']<>'character-016' or source=target then return null;end if;
 if not ml_private.stage4_on_board(s,target) or allowed='false'::jsonb then return '[]'::jsonb;end if;if allowed='true'::jsonb then return null;end if;
 return jsonb_build_array(ml_private.stage3_task('e-consent',jsonb_build_object('actor',target,'data',jsonb_build_object('source',source,'resume',resume,'root',root))));end $$;
create or replace function ml_private.p3e_moved(s jsonb,origin text,destination text,root text) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare tasks jsonb:='[]';begin
 if ml_private.p3e_enabled(s) and origin<>destination then s:=jsonb_set(s,array['stage3','e','moved',root],'true');if s->'movement'='null'::jsonb or root<>'move'||(s#>>'{movement,gearRoot}') then tasks:=jsonb_build_array(ml_private.stage3_task('e-egg',jsonb_build_object('data',jsonb_build_object('root',root))));end if;end if;return s||jsonb_build_object('_eggTasks',tasks);end $$;
create or replace function ml_private.p3e_end_move(s jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,ml_private as $$declare root text:=ml_private.p3e_root(s);begin
 if ml_private.p3e_enabled(s) and s->'movement'<>'null'::jsonb then s:=jsonb_set(s,'{stage3,e,current}',to_jsonb(root));if s#>>array['stage3','e','moved',root]='true' then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('e-egg',jsonb_build_object('data',jsonb_build_object('root',root)))));end if;end if;return s;end $$;
create or replace function ml_private.p3e_group_allowed(s jsonb,a integer,target integer,locked boolean default false) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select ml_private.stage4_on_board(s,target) and not(s#>>array['players',target::text,'character']='character-027' and jsonb_array_length(s#>array['players',target::text,'hand'])=1) and ml_private.character_effect_allowed(jsonb_build_object('origin',case when locked then 'role-locked' else 'role-active' end,'actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character'])$$;
create or replace function ml_private.p3e_neighbours(s jsonb,a integer,voluntary boolean default false) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(to_jsonb(cell) order by ord),'[]') from (select ml_private.stage3_direction_cell(s#>>array['players',a::text,'cell'],d) cell,ord from unnest(array['up','right','down','left']) with ordinality q(d,ord)) t where ml_private.stage4_on_board(s,a) and not(voluntary and ml_private.stage3_mount_blocked(s,a)) and cell is not null and ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)) and ml_private.stage3_can_enter(s,a,cell)$$;
create or replace function ml_private.p3e_force_cells(s jsonb,target integer,data jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(ml_private.p3e_neighbours(s,target)) with ordinality q(v,ord) where case when data->>'mode'='away' then ml_private.distance_for_version(s->>'version',ml_private.playtest_relocation_cell(s,target,s#>>array['players',target::text,'cell'],v#>>'{}'),data->>'base')>ml_private.distance_for_version(s->>'version',s#>>array['players',target::text,'cell'],data->>'base') else (select min(ml_private.distance_for_version(s->>'version',ml_private.playtest_relocation_cell(s,target,s#>>array['players',target::text,'cell'],v#>>'{}'),c->>'id')) from ml_private.arr(ml_private.game_data(s,'cells')) c where c->>'region'=data->>'region')<ml_private.stage4_region_distance(s,target,data->>'region') end$$;
create or replace function ml_private.p3e_relocate(s jsonb,a integer,cell text,voluntary boolean,carry boolean,reactive boolean,source integer,root text) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare skip jsonb:=s->'_gearReactiveSkip';begin
 s:=s||jsonb_build_object('_eCause',jsonb_build_object('source',source,'root',root));if not reactive then s:=s||jsonb_build_object('_gearReactiveSkip',true);end if;
 s:=ml_private.stage3_relocate(s,a,cell,voluntary,carry);s:=s-'_gearReactiveSkip'-'_eCause';if skip is not null then s:=s||jsonb_build_object('_gearReactiveSkip',skip);end if;return s;end $$;
create or replace function ml_private.p3e_skill(s jsonb,a integer,kind text,region text) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare cost integer:=case when kind='gas' then 1 else 2 end;data jsonb;t integer;tasks jsonb:='[]';begin
 perform ml_private.need(ml_private.p3e_enabled(s) and ml_private.stage4_on_board(s,a) and s#>>array['players',a::text,'character']=case when kind='gas' then 'character-014' else 'character-038' end,'本角色不能发动此技能');
 if kind='escape' then perform ml_private.need(s#>>array['stage3','e','escapeUsed',a::text]='false' and region is not null and ml_private.version_catalog(s->>'version')#>'{mapDefinition,regions}' ? region,'逃生演习次数或地区无效');end if;
 perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=cost,'技能需要'||cost||'AP');s:=ml_private.p3d_pay(s,a,cost);if kind='escape' then s:=jsonb_set(s,array['stage3','e','escapeUsed',a::text],'true');end if;
 data:=jsonb_build_object('root',ml_private.p3e_root(s),'mode',case when kind='gas' then 'away' else 'toward' end,'base',s#>array['players',a::text,'cell'])||case when region is not null then jsonb_build_object('region',region) else '{}'::jsonb end;
 for t in select (v#>>'{}')::int from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a and ml_private.p3e_group_allowed(s,a,(v#>>'{}')::int) loop tasks:=tasks||jsonb_build_array(ml_private.stage3_task('e-force',jsonb_build_object('actor',a,'target',t,'data',data)));end loop;
 if kind='escape' then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('e-escape-hit',jsonb_build_object('actor',a,'data',data)));end if;s:=jsonb_set(s,'{queue}',(s->'queue')||tasks);return ml_private.emit(s,'skill','S'||(a+1)||' '||case when kind='gas' then '释放毒气' else '逃生演习' end||'，支付'||cost||'AP');end $$;
create or replace function ml_private.p3e_end_tasks(s jsonb) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3e_enabled(s) and s#>>array['players',s->>'active','character']='character-038' then jsonb_build_array(ml_private.stage3_task('e-highest',jsonb_build_object('actor',s->'active','data',jsonb_build_object('root','end'||(s#>>'{stage3,turn}'))))) else '[]'::jsonb end$$;
create or replace function ml_private.p3e_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer:=(t->>'target')::int;data jsonb:=t->'data';root text:=data->>'root';source integer:=(data->>'source')::int;action text:=t->>'action';cells jsonb;gate jsonb;tasks jsonb:='[]';egg integer;max_hp integer;max_distance integer;origin text;destination text;first_cell text;second_cell text;c jsonb:=s#>'{cardStack,stack,-1}';begin
 if root is not null then s:=jsonb_set(s,'{stage3,e,current}',to_jsonb(root));end if;
 if action='e-consent' then if ml_private.stage4_on_board(s,a) then s:=ml_private.select_choice(s,'move-consent',a,at,jsonb_build_object('data',data)||case when source is null then '{}'::jsonb else jsonb_build_object('source',source) end);end if;return s;end if;
 if action='e-relocate' then if ml_private.stage4_on_board(s,a) and ml_private.stage4_board_empty(s,a,data->>'cell',jsonb_build_array(a)) and ml_private.stage3_can_enter(s,a,data->>'cell') then s:=ml_private.p3e_relocate(s,a,data->>'cell',(data->>'voluntary')::boolean,(data->>'carry')::boolean,(data->>'reactive')::boolean,source,root);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;end if;
 if action='e-egg' then select (v->>'seat')::int into egg from ml_private.arr(s->'players') v where v->>'character'='character-024' and ml_private.stage4_on_board(s,(v->>'seat')::int);if egg is null or s#>>array['stage3','e','eggUsed',root]='true' or coalesce(s#>>array['stage3','e','moved',root],'false')<>'true' then return s;end if;cells:=ml_private.p3e_neighbours(s,egg,true);if jsonb_array_length(cells)>0 then s:=jsonb_set(s,array['stage3','e','eggUsed',root],'true');s:=ml_private.select_choice(s,'egg-move',egg,at,jsonb_build_object('cells',cells,'data',jsonb_build_object('root',root)));end if;return s;end if;
 if action='e-highest' then if not ml_private.stage4_on_board(s,a) then return s;end if;select max((v->>'hp')::int) into max_hp from ml_private.arr(s->'players') v where ml_private.stage4_on_board(s,(v->>'seat')::int);for target in select (v#>>'{}')::int from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a and (s#>>array['players',v#>>'{}','hp'])::int=max_hp and ml_private.p3e_group_allowed(s,a,(v#>>'{}')::int,true) loop tasks:=tasks||jsonb_build_array(ml_private.stage3_task('e-force',jsonb_build_object('actor',a,'target',target,'data',jsonb_build_object('root',root,'mode','away','base',s#>array['players',a::text,'cell'],'locked',true))));end loop;return ml_private.stage3_prepend(s,tasks);end if;
 if action='e-force' then if not ml_private.stage4_on_board(s,a) or not ml_private.p3e_group_allowed(s,a,target,coalesce((data->>'locked')::boolean,false)) then return s;end if;cells:=ml_private.p3e_force_cells(s,target,data);if jsonb_array_length(cells)=0 then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;return ml_private.select_choice(s,'force-step',a,at,jsonb_build_object('source',target,'cells',cells,'data',data));end if;
 if action='e-escape-hit' then if not ml_private.stage4_on_board(s,a) then return s;end if;select max(ml_private.stage4_region_distance(s,(v#>>'{}')::int,data->>'region')) into max_distance from ml_private.arr(s->'order') v where (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int);select coalesce(jsonb_agg(jsonb_build_object('target',v,'amount',1,'source',a,'category','response') order by ord),'[]') into tasks from jsonb_array_elements(s->'order') with ordinality q(v,ord) where (v#>>'{}')::int<>a and ml_private.stage4_on_board(s,(v#>>'{}')::int) and ml_private.stage4_region_distance(s,(v#>>'{}')::int,data->>'region')=max_distance and ml_private.p3e_group_allowed(s,a,(v#>>'{}')::int);s:=ml_private.damage(s,tasks);return ml_private.stage3_prepend(s,s->'_triggers')-'_triggers';end if;
 if action='e-off-map' then if not ml_private.stage4_on_board(s,target) then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;s:=jsonb_set(s,array['stage4','offMap',target::text],'true');s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');return ml_private.emit(s,'off-map','S'||(target+1)||' 移出地图，等待下个个人开始返回');end if;
 if action='e-swap' then if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or c is null or not ml_private.stage3_card_allowed(s,a,c->>'definition',c->'effect') or not ml_private.stage3_card_allowed(s,target,c->>'definition',c->'effect') then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;
 origin:=s#>>array['players',a::text,'cell'];destination:=s#>>array['players',target::text,'cell'];first_cell:=ml_private.playtest_relocation_cell(s,a,origin,destination,jsonb_build_array(target));second_cell:=ml_private.playtest_relocation_cell(s,target,destination,origin,jsonb_build_array(a));if first_cell is null or second_cell is null or first_cell=second_cell or not ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,first_cell,jsonb_build_array(a,target)) or not ml_private.stage3_empty_entry(ml_private.stage3_board(s),target,second_cell,jsonb_build_array(a,target)) or not ml_private.stage3_can_enter(s,a,first_cell) or not ml_private.stage3_can_enter(s,target,second_cell) or ml_private.stage3_mount_blocked(s,a) then return s;end if;
 s:=jsonb_set(s,array['stage4','offMap',target::text],'true');s:=ml_private.p3e_relocate(s,a,first_cell,true,true,true,a,root);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=jsonb_set(s,array['stage4','offMap',target::text],'false');s:=ml_private.p3e_relocate(s,target,second_cell,false,true,true,a,root);return ml_private.stage3_prepend(s,tasks||(s->'_relocationTasks'))-'_relocationTasks';end if;
 if action='e-elbow' then if not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) or not ml_private.stage4_board_empty(s,target,data->>'cell',jsonb_build_array(target)) or not ml_private.stage3_can_enter(s,target,data->>'cell') or not ml_private.stage3_can_enter(s,a,s#>>array['players',target::text,'cell']) or ml_private.stage3_mount_blocked(s,a) then return s;end if;gate:=ml_private.p3e_gate(s,target,a,jsonb_build_array(t),root);if gate is not null then return ml_private.stage3_prepend(s,gate);end if;origin:=s#>>array['players',target::text,'cell'];s:=ml_private.p3e_relocate(s,target,data->>'cell',false,true,true,a,root);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.p3e_relocate(s,a,origin,true,true,true,a,root);return ml_private.stage3_prepend(s,tasks||(s->'_relocationTasks'))-'_relocationTasks';end if;
 raise exception '未知E批任务';end $$;
create or replace function ml_private.p3e_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;data jsonb:=c->'data';root text:=data->>'root';accepted boolean:=not timeout and coalesce((cmd->>'accept')::boolean,false);cell text:=cmd->>'cell';cells jsonb;target integer:=(c->>'source')::int;k text;begin
 s:=jsonb_set(s,'{stage3,e,current}',to_jsonb(root));if c->>'kind'='move-consent' then k:=root||':'||coalesce(data->>'source','environment')||':'||a;s:=jsonb_set(s,array['stage3','e','permissions',k],to_jsonb(accepted));s:=ml_private.emit(s,'skill','S'||(a+1)||' 不动：'||case when accepted then '同意' else '拒绝' end||'本次位移链');return ml_private.stage3_prepend(s,data->'resume');end if;
 if c->>'kind'='egg-move' then if not timeout and cell is not null then perform ml_private.need(c->'cells' ? cell and ml_private.p3e_neighbours(s,a,true) ? cell,'体育部部长落点不合法');s:=ml_private.p3e_relocate(s,a,cell,true,true,true,a,root);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;end if;
 cells:=ml_private.p3e_force_cells(s,target,data);if timeout then cell:=cells->>0;end if;if cell is null then perform ml_private.need(jsonb_array_length(cells)=0,'请选择强制位移方向');return s;end if;perform ml_private.need(c->'cells' ? cell and cells ? cell,'强制位移落点已失效');s:=ml_private.p3e_relocate(s,target,cell,false,true,true,a,root);return ml_private.stage3_prepend(s,s->'_relocationTasks')-'_relocationTasks';end $$;
